import{_ as t,a,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Create Section","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"Create Section","query":"curl -X POST \\"https://your-domain.com/api/admin/appearance/themes/default/sections?channel=1\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Content-Type: application/json\\" \\\\\\n  -d '{ \\"name\\": \\"Summer Banner\\", \\"type\\": \\"image_carousel\\" }'\\n","response":"{\\n  \\"id\\": 12,\\n  \\"name\\": \\"Summer Banner\\",\\n  \\"type\\": \\"image_carousel\\",\\n  \\"themeCode\\": \\"default\\",\\n  \\"channelId\\": 1,\\n  \\"sortOrder\\": 5,\\n  \\"status\\": 0,\\n  \\"draftStatus\\": true,\\n  \\"draftSortOrder\\": null,\\n  \\"hasDraft\\": true,\\n  \\"isPinned\\": false,\\n  \\"createdAt\\": \\"2026-08-26T11:04:02+05:30\\",\\n  \\"updatedAt\\": \\"2026-08-26T11:04:02+05:30\\",\\n  \\"translations\\": [],\\n  \\"message\\": \\"Section created successfully.\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/appearance/sections/create.md","filePath":"api/rest-api/admin/appearance/sections/create.md","lastUpdated":1789385991000}`),s={name:"api/rest-api/admin/appearance/sections/create.md"};function n(d,e,i,c,h,l){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="create-section" tabindex="-1">Create Section <a class="header-anchor" href="#create-section" aria-label="Permalink to &quot;Create Section&quot;">​</a></h1><p>Adds a section to a theme and channel. The section is created <strong>switched off with a staged on-state</strong>, so it is drawn in the editor and its preview but not on the storefront until it has been built and published.</p><p>Content is not part of creation. Add it with <a href="/api/rest-api/admin/appearance/sections/draft.html">Stage edits</a> or <a href="/api/rest-api/admin/appearance/sections/update.html">Update section</a> afterwards.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/admin/appearance/themes/{code}/sections</code></td><td>Create a section</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>Theme the section belongs to.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>channel</code></td><td>Channel the section is created for. Falls back to the current channel.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>Yes</td><td>Name shown in the editor.</td></tr><tr><td><code>type</code></td><td>string</td><td>Yes</td><td><code>image_carousel</code>, <code>product_carousel</code>, <code>category_carousel</code>, <code>footer_links</code>, <code>static_content</code> or <code>services_content</code>.</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><p>The created section, same shape as <a href="/api/rest-api/admin/appearance/sections/detail.html">Get section</a>, with <code>message</code> set.</p><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><ul><li><strong>Add a promo banner to one channel</strong> — create with <code>type: image_carousel</code>, upload the slide through <a href="/api/rest-api/admin/appearance/sections/media.html">Upload media</a>, stage the returned path in the section&#39;s options, then publish.</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong><code>status</code> comes back <code>0</code> on purpose.</strong> A new section is off until published; sending a status in the body does not change that, and switching it on is <a href="/api/rest-api/admin/appearance/sections/status.html">Stage status</a> followed by a publish.</li><li><strong><code>sortOrder</code> is assigned, not chosen.</strong> The section is appended to the end and the whole set is renumbered, with <code>footer_links</code> kept last — send a <a href="/api/rest-api/admin/appearance/sections/reorder.html">Stage order</a> afterwards to place it.</li><li><strong>A channel gets one footer.</strong> Creating a second <code>footer_links</code> section for the same theme and channel is rejected with <code>422</code>.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>When</th></tr></thead><tbody><tr><td><code>404</code></td><td>Unknown theme code.</td></tr><tr><td><code>422</code></td><td><code>name</code> missing, <code>type</code> missing or not one of the six, or a second <code>footer_links</code> section.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Requires <code>appearance.sections.create</code>.</p>',21)]))}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
